INSERT INTO `qs_products` VALUES (77,66,'EGCGBFK001','[]','Fastrack E-Gift Card','Fastrack is a cool, hip accessories brand that comes with an attitude. A brainchild of the World of Titan, Fastrack has revolutionized the way people perceive accessories. Within minutes of your purchase, your gift recipient receives the Fastrack e-Gift card and can go shopping!','{\"price\":\"RANGE\",\"type\":\"RANGE\",\"min\":\"10\",\"max\":\"10000\",\"denominations\":[\"10\",\"100\",\"1000\",\"5000\",\"10000\"],\"currency\":{\"code\":\"INR\",\"symbol\":\"\\u20b9\",\"numericCode\":\"356\"},\"cpg\":[]}',0,NULL,'{\"price\":\"RANGE\",\"type\":\"RANGE\",\"min\":\"10\",\"max\":\"10000\",\"denominations\":[\"10\",\"100\",\"1000\",\"5000\",\"10000\"],\"currency\":{\"code\":\"INR\",\"symbol\":\"\\u20b9\",\"numericCode\":\"356\"},\"cpg\":[]}','DIGITAL','1','{\"code\":\"INR\",\"symbol\":\"\\u20b9\",\"numericCode\":\"356\"}','356','{\"thumbnail\":\"https:\\/\\/gbdev.s3.amazonaws.com\\/uat\\/product\\/EGCGBFK001\\/d\\/thumbnail\\/66_microsite.png\",\"mobile\":\"https:\\/\\/gbdev.s3.amazonaws.com\\/uat\\/product\\/EGCGBFK001\\/d\\/mobile\\/66_microsite.png\",\"base\":\"https:\\/\\/gbdev.s3.amazonaws.com\\/uat\\/product\\/EGCGBFK001\\/d\\/image\\/66_microsite.png\",\"small\":\"https:\\/\\/gbdev.s3.amazonaws.com\\/uat\\/product\\/EGCGBFK001\\/d\\/small_image\\/66_microsite.png\"}','{\"link\":\"https:\\/\\/woohooqa.app.link\\/e\\/6CjTB9artfb\",\"content\":\"Amazon Gift Cards (\\\"GCs\\\") are issued by the Qwikcilver Solutions Private limited (\\\"Qwikcilver\\\"). Credit and Debit Cards issued outside India cannot be used to purchase Amazon.in Gift Cards.<br\\/>To add your GC to your Amazon Pay balance, visit www.amazon.in\\/addgiftcard<br\\/>Beneficiary can apply the 14 digit code (under scratch card) on amazon.in\\/addgiftcard and add the gift card balance in his\\/her Amazon.in account. This balance gets automatically applied at the time of next purchase. There is no cap on number of gift cards that can be added to an account.<br\\/>Amazon Pay balance is a sum of all balances associated with the GCs in your Amazon.in account.<br\\/>Amazon Pay balance are redeemable across all products on Amazon.in except apps, certain global store products and other Amazon.in gift cards.<br\\/>Amazon Pay balance must be used only towards the purchase of eligible products on amazon.in<br\\/>The GCs, including any unused Amazon Pay balance, expire one year from the date of issuance of the GC<br\\/>GCs cannot be transferred for value or redeemed for the cash.<br\\/>Qwikcilver, Amazon Seller Services Private Limited (Amazon) or their affiliates are not responsible if a GC is lost, stolen, destroyed or used without permission.<br\\/>For Complete terms and conditions, see www.amazon.in\\/giftcardtnc<br\\/>Amazon.in logo\\/trademark is an IP of Amazon or its affiliates and the Qwikcilver trademark\\/logo is an IP of Qwikcilver.<br\\/>To redeem your GC, visit www.amazon.in\\/addgiftcard<br\\/>E-Gift Cards are normally delivered instantly. But sometimes due to system issues, the delivery can be delayed up-to 24 - 48 hours.<br\\/>For detailed T&Cs of this E-Gift Card please refer www.woohoo.in\\/termsandconditions<br\\/>Certain merchants may provide you services only on the pre-condition that you allow us to hold balances in your Amazon Pay balance: Gift Card till the service completion by the merchant. However, your prior consent would be taken before holding such balances. In such cases, you agree and authorize us to: (i) hold your balance until service completion; and (ii) fail the transaction if your balance in the Amazon Pay Gift Card is less than the actual amount charged by the merchant at the end of the services.<br\\/>You may request for revalidation of any expired Gift Cards. Upon receipt of such request, the Gift Card may be revalidated after due verification and subject to applicable terms and conditions.<br\\/>No returns and no refunds on gift cards, e-gift cards and gif